#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* No argument supplied */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse the argument as a decimal integer */
    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);

    /* Bad input: no digits or extra characters, or overflow */
    if (endptr == argv[1] || *endptr != '\0' ||
        ((n == LONG_MAX || n == LONG_MIN) && errno == ERANGE)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* Out‑of‑range check (the original program limits to 1 000 000 000) */
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Numbers smaller than 2 have no prime factors */
    if (n < 2) {
        puts("NONE");
        return 0;
    }

    /* Prime‑factorisation */
    long remaining = n;
    int first = 1;                 /* true while nothing has been printed yet */

    for (long p = 2; p * p <= remaining; ++p) {
        if (remaining % p == 0) {
            int exp = 0;
            while (remaining % p == 0) {
                remaining /= p;
                ++exp;
            }
            if (!first) putchar(' ');
            printf("%ld^%d", p, exp);
            first = 0;
        }
    }

    /* If something is left, it is a prime > sqrt(original n) */
    if (remaining > 1) {
        if (!first) putchar(' ');
        printf("%ld^1", remaining);
    }

    putchar('\n');
    return 0;
}
